import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);
const LAB_DIR = path.resolve(__dirname, '..');

function readJson(relPath) {
  return JSON.parse(fs.readFileSync(path.join(LAB_DIR, relPath), 'utf8'));
}

const bundle = {
  generatedAt: '2026-11-25',
  storyboard: readJson('data/storyboard.json'),
  seasonIndex: readJson('data/season-index.json'),
  candidate: readJson('data/proposed-character-candidate.json'),
  manifest: readJson('data/manifest.json'),
  clips: {
    'animations/anim-a-signal-detected/clip.json': readJson('animations/anim-a-signal-detected/clip.json'),
    'animations/anim-b-courier-move/clip.json': readJson('animations/anim-b-courier-move/clip.json'),
    'animations/anim-c-archive-reaction/clip.json': readJson('animations/anim-c-archive-reaction/clip.json'),
    'animations/anim-d-message-preserved/clip.json': readJson('animations/anim-d-message-preserved/clip.json'),
  },
};

const outPath = path.join(LAB_DIR, 'data/inline-bundle.js');
const content = `/* Auto-generated by scripts/build-inline-bundle.mjs for zero-server file:// portability */\nwindow.__MW_COMIC_LAB_BUNDLE__ = ${JSON.stringify(bundle, null, 2)};\n`;
fs.writeFileSync(outPath, content, 'utf8');
console.log(JSON.stringify({ ok: true, out: 'data/inline-bundle.js', bytes: Buffer.byteLength(content, 'utf8') }));
